import requests
queries=['Drosophila glob1 oogenesis cytoskeleton','Drosophila globin 1 ovary actin','Drosophila glob1 ovarian']
for q in queries:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':10},timeout=20)
 print('\nQUERY',q,'STATUS',r.status_code)
 ids=r.json().get('esearchresult',{}).get('idlist',[])
 print('PMIDS',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'))

import requests, xml.etree.ElementTree as ET
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':'27503269','retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for art in root.findall('.//PubmedArticle'):
 for el in art.findall('.//ArticleTitle'): print('TITLE:', ''.join(el.itertext()))
 for el in art.findall('.//Abstract/AbstractText'):
  print('ABSTRACT:', el.attrib.get('Label',''), ''.join(el.itertext()))
 print('JOURNAL:', ''.join(art.find('.//Journal/Title').itertext()) if art.find('.//Journal/Title') is not None else '')
 print('YEAR:', art.findtext('.//PubDate/Year'))
